const uid = prefix => `${prefix}-${crypto.randomUUID()}`;
const clone = value => structuredClone(value);
const root = 'production/';
function availableLoras(store) { return [...new Set([...store.presets.flatMap(p => p.variants.flatMap(v => v.loras.map(l => l.path))), 'characters/default-character.safetensors', 'detail/refiner.safetensors'])]; }
