  const group = { id: 'group-character', categoryId: 'category-group', folderId: null, name: '角色与光影', members: [{ id: 'member-character', slotIndex: 0, presetId: presets[0].id, variantId: presets[0].variants[0].id }, { id: 'member-style', slotIndex: 1, presetId: presets[2].id, variantId: presets[2].variants[0].id }] };
  const sections = ['角色草图', '场景光影', '最终组选'].map((name, i) => ({ ...emptySection(name), id: `template-section-${i + 1}`, params: { ...emptySection().params, aspectRatio: i === 1 ? '16:9' : '2:3', shortSidePx: 768, batchSize: i === 2 ? 4 : 2 }, prompt: 'cinematic portrait, soft lighting, refined detail', negative: 'low quality, blurry, extra fingers', notes: i === 2 ? '精修并选择最终画面。' : '', promptBlocks: [{ id: `block-${i}`, bindingId: `binding-${i}`, name: '主体', positive: 'cinematic portrait, soft lighting, refined detail', negative: 'low quality, blurry, extra fingers' }], loras: presets[0].variants[0].loras.map(l => ({ ...clone(l), id: `section-lora-${i}`, bindingId: `binding-${i}` })), presetIds: [presets[0].id], bindings: [{ id: `binding-${i}`, presetId: presets[0].id, variantId: presets[0].variants[0].id }] }));
